			dst_val->val.f = src1_val->val.f * src2_val->val.f;
			break;
		case NOCT_VALUE_DOUBLE:
			dst_val->type = NOCT_VALUE_DOUBLE;
			dst_val->val.lf = (double)src1_val->val.f * src2_val->val.lf;
			break;
		default:
